import { describe, it, expect } from "vitest";
import { protectedResourceHandler } from "../src/index";

describe("auth", () => {
  describe("resource metadata URL to resource identifier mapping", () => {
    const handler = protectedResourceHandler({
      authServerUrls: ["https://auth-server.com"],
    });

    const testCases = [
      // Default well-known URI suffix (oauth-protected-resource)
      {
        resourceMetadata: 'https://resource-server.com/.well-known/oauth-protected-resource',
        resource: 'https://resource-server.com',
      },
      {
        resourceMetadata: 'https://resource-server.com/.well-known/oauth-protected-resource/my-resource',
        resource: 'https://resource-server.com/my-resource',
      },
      {
        resourceMetadata: 'https://resource-server.com/.well-known/oauth-protected-resource/foo/bar',
        resource: 'https://resource-server.com/foo/bar',
      },
      // Ensure ports work
      {
        resourceMetadata: 'https://resource-server.com:8443/.well-known/oauth-protected-resource',
        resource: 'https://resource-server.com:8443',
      },
      // Example well-known URI suffix from RFC 9728 (example-protected-resource)
      {
        resourceMetadata: 'https://resource-server.com/.well-known/example-protected-resource',
        resource: 'https://resource-server.com',
      },
      {
        resourceMetadata: 'https://resource-server.com/.well-known/example-protected-resource/my-resource',
        resource: 'https://resource-server.com/my-resource',
      },
    ] as const;

    testCases.forEach(testCase => {
      it(`${testCase.resourceMetadata} → ${testCase.resource}`, async () => {
        const req = new Request(testCase.resourceMetadata);
        const res = handler(req);
        const json = await res.json();
        expect(json.resource).toBe(testCase.resource);
      });
    });
  });

  describe("proxy header support", () => {
    const handler = protectedResourceHandler({
      authServerUrls: ["https://auth-server.com"],
    });

    it("uses X-Forwarded-Host and X-Forwarded-Proto headers", async () => {
      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource", {
        headers: {
          "X-Forwarded-Host": "example.org",
          "X-Forwarded-Proto": "https",
        },
      });
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://example.org");
    });

    it("handles X-Forwarded-Host with multiple values (uses first)", async () => {
      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource", {
        headers: {
          "X-Forwarded-Host": "example.org, proxy1.internal, proxy2.internal",
          "X-Forwarded-Proto": "https",
        },
      });
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://example.org");
    });

    it("defaults to https when X-Forwarded-Proto is missing", async () => {
      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource", {
        headers: {
          "X-Forwarded-Host": "example.org",
        },
      });
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://example.org");
    });

    it("uses RFC 7239 Forwarded header", async () => {
      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource", {
        headers: {
          "Forwarded": "host=example.org;proto=https",
        },
      });
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://example.org");
    });

    it("preserves path when using proxy headers", async () => {
      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource/my-resource", {
        headers: {
          "X-Forwarded-Host": "example.org",
          "X-Forwarded-Proto": "https",
        },
      });
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://example.org/my-resource");
    });

    it("falls back to req.url when no proxy headers present", async () => {
      const req = new Request("https://direct-server.com/.well-known/oauth-protected-resource");
      const res = handler(req);
      const json = await res.json();
      expect(json.resource).toBe("https://direct-server.com");
    });
  });

  describe("explicit resourceUrl override", () => {
    it("uses explicit resourceUrl when provided", async () => {
      const handler = protectedResourceHandler({
        authServerUrls: ["https://auth-server.com"],
        resourceUrl: "https://my-public-domain.com",
      });

      const req = new Request("http://localhost:3000/.well-known/oauth-protected-resource", {
        headers: {
          "X-Forwarded-Host": "different-proxy.org",
          "X-Forwarded-Proto": "https",
        },
      });
      const res = handler(req);
      const json = await res.json();
      // Should use explicit override, ignoring both req.url and proxy headers
      expect(json.resource).toBe("https://my-public-domain.com");
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { z } from "zod";
import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { createMcpHandler } from "../src/index";
import { nodeToWebHandler } from "./helpers";

type RegisteredTool = {
  name: string;
  description: string;
  inputSchema: unknown;
  execute: (args: unknown) => Promise<unknown>;
};

describe("createMcpHandler WebMCP option", () => {
  it("serves the bridge script with the embedded allowlist", async () => {
    const handler = createMcpHandler(() => {}, {
      experimental_webMcp: { tools: ["echo"] },
    });
    const res = await handler(
      new Request("https://example.com/api/mcp?webmcp-script"),
    );
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toBe(
      "text/javascript; charset=utf-8",
    );
    const script = await res.text();
    expect(script).toContain('"endpoint":"https://example.com/api/mcp"');
    expect(script).toContain('"tools":["echo"]');
    expect(script).toContain('"credentials":"same-origin"');
  });

  it("escapes config so it cannot break out of an inline script tag", async () => {
    const handler = createMcpHandler(() => {}, {
      experimental_webMcp: {
        tools: ["</script><script>alert(1)</script>"],
      },
    });
    const response = await handler(
      new Request("http://localhost/api/mcp?webmcp-script"),
    );
    const script = await response.text();
    expect(script).not.toContain("</script>");
  });

  it("supports HEAD requests and configured cache control", async () => {
    const handler = createMcpHandler(() => {}, {
      experimental_webMcp: {
        tools: [],
        cacheControl: "private, no-store",
      },
    });
    const res = await handler(
      new Request("http://localhost/api/mcp?webmcp-script", {
        method: "HEAD",
      }),
    );
    expect(res.status).toBe(200);
    expect(res.headers.get("cache-control")).toBe("private, no-store");
    expect(await res.text()).toBe("");
  });

  it("requires an explicit tools allowlist", () => {
    expect(() =>
      createMcpHandler(() => {}, { experimental_webMcp: {} as never }),
    ).toThrow("`tools` must be an array of tool names");
  });
});

describe("webmcp bridge e2e", () => {
  let server: Server;
  let endpoint: string;

  beforeEach(async () => {
    const mcpHandler = createMcpHandler(
      (server) => {
        server.registerTool(
          "echo",
          {
            description: "Echo a message",
            inputSchema: z.object({ message: z.string() }),
          },
          async ({ message }) => ({
            content: [{ type: "text", text: `Tool echo: ${message}` }],
          }),
        );
        server.registerTool(
          "secret",
          {
            description: "Not for the web",
            inputSchema: z.object({}),
          },
          async () => ({ content: [{ type: "text", text: "secret" }] }),
        );
      },
      { experimental_webMcp: { tools: ["echo"] } },
    );

    server = createServer(nodeToWebHandler(mcpHandler));
    await new Promise<void>((resolve) => {
      server.listen(0, () => resolve());
    });
    const port = (server.address() as AddressInfo | null)?.port;
    endpoint = `http://localhost:${port}/api/mcp`;
  });

  afterEach(() => {
    server.close();
  });

  async function runBridgeScript(): Promise<RegisteredTool[]> {
    const script = await fetch(`${endpoint}?webmcp-script`).then((response) =>
      response.text(),
    );

    const registered: RegisteredTool[] = [];
    const provider = {
      registerTool: (tool: RegisteredTool) => {
        registered.push(tool);
      },
    };
    // Shadow the globals the script feature-detects; fetch stays global.
    new Function("navigator", "document", script)(
      { modelContext: provider },
      undefined,
    );

    await vi.waitFor(() => {
      expect(registered.length).toBeGreaterThan(0);
    });
    return registered;
  }

  it("registers only allowlisted tools with the WebMCP provider", async () => {
    const registered = await runBridgeScript();
    expect(registered).toHaveLength(1);
    expect(registered[0].name).toBe("echo");
    expect(registered[0].description).toBe("Echo a message");
    expect(registered[0].inputSchema).toMatchObject({
      type: "object",
      properties: { message: { type: "string" } },
      required: ["message"],
    });
  });

  it("executes tool calls against the MCP endpoint", async () => {
    const [echo] = await runBridgeScript();
    const result = (await echo.execute({ message: "Are you there?" })) as {
      content: Array<{ type: string; text: string }>;
    };
    expect(result.content[0].text).toBe("Tool echo: Are you there?");
  });

  it("is a no-op when no WebMCP provider exists", async () => {
    const script = await fetch(`${endpoint}?webmcp-script`).then((response) =>
      response.text(),
    );
    expect(() =>
      new Function("navigator", "document", script)(undefined, undefined),
    ).not.toThrow();
  });
});

import { describe, expect, it, vi } from "vitest";
import { readFileSync } from "node:fs";
import { ModuleKind, ScriptTarget, transpileModule } from "typescript";
import { withMcpAuth } from "../src/index";
import { createWebMcpScriptHandler } from "../src/webmcp/script-handler";

type Tool = {
  name: string;
  title?: string;
  description?: string;
  inputSchema?: object;
  annotations?: { title?: string; readOnlyHint?: boolean };
};
type RegisteredTool = Tool & {
  execute: (
    args: object,
    options?: { signal: AbortSignal },
  ) => Promise<unknown>;
};
type RpcRequest = { id?: number; method: string; params?: { cursor?: string } };

async function runScript({
  tools = [{ name: "echo" }],
  register = async (_tool: RegisteredTool) => {},
  respond,
  navigatorProvider,
}: {
  tools?: Tool[];
  register?: (tool: RegisteredTool) => void | Promise<void>;
  respond?: (
    body: RpcRequest,
    init: RequestInit,
  ) => Response | Promise<Response> | undefined;
  navigatorProvider?: object;
} = {}) {
  const registered: RegisteredTool[] = [];
  const warn = vi.fn();
  const fetchMock = vi.fn(async (_url: string, init: RequestInit) => {
    const body = JSON.parse(init.body as string) as RpcRequest;
    const response = await respond?.(body, init);
    if (response) return response;
    if (body.method === "notifications/initialized")
      return new Response(null, { status: 202 });
    return Response.json({
      jsonrpc: "2.0",
      id: body.id,
      result:
        body.method === "initialize"
          ? { protocolVersion: "2025-06-18" }
          : { tools },
    });
  });
  const registerTool = vi.fn(async (tool: RegisteredTool) => {
    if (!tool.description) throw new Error("WebMCP requires a description");
    await register(tool);
    registered.push(tool);
  });
  const script = await createWebMcpScriptHandler({
    endpoint: "/api/mcp",
    tools: tools.map((tool) => tool.name),
  })(new Request("https://example.com/webmcp.js")).text();
  new Function("document", "navigator", "fetch", "console", script)(
    { modelContext: { registerTool } },
    { modelContext: navigatorProvider },
    fetchMock,
    { warn },
  );
  return { registered, registerTool, fetchMock, warn };
}

describe("WebMCP provider contract", () => {
  it("prefers document.modelContext and provides a nonempty description", async () => {
    const legacyRegister = vi.fn();
    const { registered } = await runScript({
      navigatorProvider: { registerTool: legacyRegister },
    });
    await vi.waitFor(() => expect(registered).toHaveLength(1));
    expect(registered[0].description).toBe("echo");
    expect(legacyRegister).not.toHaveBeenCalled();
  });

  it("preserves display titles and explicit read-only hints", async () => {
    const { registered } = await runScript({
      tools: [
        {
          name: "search",
          title: "Search docs",
          annotations: { readOnlyHint: true },
        },
        { name: "write", annotations: { title: "Write a note" } },
      ],
    });
    await vi.waitFor(() => expect(registered).toHaveLength(2));
    expect(registered[0]).toMatchObject({
      title: "Search docs",
      description: "Search docs",
      annotations: { readOnlyHint: true },
    });
    expect(registered[1]).toMatchObject({
      title: "Write a note",
      description: "Write a note",
      annotations: { readOnlyHint: false },
    });
  });

  it.each(["sync", "async"])(
    "continues after a %s registration failure",
    async (mode) => {
      const failure = new Error("Tool already registered");
      const { registered, warn } = await runScript({
        tools: [{ name: "duplicate" }, { name: "echo" }],
        register(tool) {
          if (tool.name !== "duplicate") return;
          if (mode === "sync") throw failure;
          return Promise.reject(failure);
        },
      });
      await vi.waitFor(() => expect(registered).toHaveLength(1));
      expect(registered[0].name).toBe("echo");
      expect(warn).toHaveBeenCalledWith(
        expect.stringContaining("duplicate"),
        failure,
      );
    },
  );

  it("finds allowlisted tools on later pages without registering other tools", async () => {
    const { registered, fetchMock } = await runScript({
      respond(body) {
        if (body.method !== "tools/list") return;
        return Response.json({
          jsonrpc: "2.0",
          id: body.id,
          result: body.params?.cursor
            ? { tools: [{ name: "echo" }] }
            : { tools: [{ name: "secret" }], nextCursor: "page-2" },
        });
      },
    });
    await vi.waitFor(() => expect(registered).toHaveLength(1));
    expect(registered[0].name).toBe("echo");
    const requests = fetchMock.mock.calls.map(([, init]) =>
      JSON.parse(init.body as string),
    );
    expect(
      requests
        .filter((body) => body.method === "tools/list")
        .map((body) => body.params),
    ).toEqual([{}, { cursor: "page-2" }]);
  });

  it("aborts an in-flight fetch when the browser cancels execution", async () => {
    let signal: AbortSignal | null | undefined;
    const { registered } = await runScript({
      respond(body, init) {
        if (body.method !== "tools/call") return;
        signal = init.signal;
        return new Promise<Response>((_resolve, reject) => {
          signal!.addEventListener("abort", () => reject(signal!.reason), {
            once: true,
          });
        });
      },
    });
    await vi.waitFor(() => expect(registered).toHaveLength(1));
    const controller = new AbortController();
    const result = registered[0].execute({}, { signal: controller.signal });
    const rejected = expect(result).rejects.toMatchObject({
      name: "AbortError",
    });
    expect(signal).toBe(controller.signal);
    controller.abort();
    await rejected;
  });

  it.each(["application/json", "text/event-stream"])(
    "preserves tool error content from %s responses",
    async (contentType) => {
      const result = {
        isError: true,
        content: [{ type: "text", text: "Document does not exist" }],
      };
      const { registered } = await runScript({
        respond(body) {
          if (body.method !== "tools/call") return;
          const message = JSON.stringify({
            jsonrpc: "2.0",
            id: body.id,
            result,
          });
          return new Response(
            contentType === "application/json"
              ? message
              : `event: message\r\ndata: ${message}\r\n\r\n`,
            { headers: { "content-type": contentType } },
          );
        },
      });
      await vi.waitFor(() => expect(registered).toHaveLength(1));
      await expect(registered[0].execute({})).resolves.toEqual(result);
    },
  );
});

describe("documented cookie authentication", () => {
  // Execute the actual recipe so removing required:true from the docs regresses this test.
  const docs = readFileSync(
    new URL("../docs/AUTHORIZATION.md", import.meta.url),
    "utf8",
  );
  const source = docs.match(
    /## Browser session cookies for WebMCP[\s\S]*?```typescript\n([\s\S]*?)\n```/,
  )?.[1];
  if (!source) throw new Error("Cookie-auth documentation example not found");
  const recipe = transpileModule(source, {
    compilerOptions: { module: ModuleKind.None, target: ScriptTarget.ES2022 },
  }).outputText;
  const authInfo = {
    token: "[REDACTED]",
    clientId: "browser",
    scopes: ["read:stuff"],
  };

  it.each([
    { site: "same-origin", cookie: "session=valid", bearer: "", status: 200 },
    { site: "same-origin", cookie: "", bearer: "", status: 401 },
    { site: "same-origin", cookie: "session=expired", bearer: "", status: 401 },
    { site: "cross-site", cookie: "session=valid", bearer: "", status: 401 },
    { site: "same-site", cookie: "session=valid", bearer: "", status: 401 },
    { site: "", cookie: "session=valid", bearer: "", status: 401 },
    { site: "", cookie: "", bearer: "valid", status: 200 },
  ])(
    "returns $status for site=$site cookie=$cookie bearer=$bearer",
    async ({ site, cookie, bearer, status }) => {
      const mcpHandler = vi.fn(() => new Response("tool ran"));
      const handler = new Function(
        "withMcpAuth",
        "handler",
        "verifyOAuthToken",
        "verifySession",
        `${recipe}\nreturn authHandler;`,
      )(
        withMcpAuth,
        mcpHandler,
        (token: string) => (token === "valid" ? authInfo : undefined),
        (token: string) => (token === "valid" ? authInfo : undefined),
      );
      const response = await handler(
        new Request("https://example.com/api/mcp", {
          headers: {
            "sec-fetch-site": site,
            cookie,
            ...(bearer ? { authorization: `Bearer ${bearer}` } : {}),
          },
        }),
      );
      expect(response.status).toBe(status);
      expect(mcpHandler).toHaveBeenCalledTimes(status === 200 ? 1 : 0);
    },
  );
});

# Authorization

The MCP adapter supports the [MCP Authorization Specification](https://modelcontextprotocol.io/specification/draft/basic/authorization) through the `withMcpAuth` wrapper.

## Basic Usage

```typescript
// app/api/mcp/route.ts
import type { AuthInfo } from "@modelcontextprotocol/server";
import { createMcpHandler, withMcpAuth } from "mcp-handler";
import { z } from "zod";

const handler = createMcpHandler((server) => {
  server.registerTool(
    "echo",
    {
      title: "Echo",
      description: "Echo a message",
      inputSchema: z.object({ message: z.string() }),
    },
    async ({ message }, ctx) => {
      // Access auth info via ctx.http?.authInfo
      const authInfo = ctx.http?.authInfo;
      return {
        content: [
          {
            type: "text",
            text: `Echo: ${message}${
              authInfo?.token ? ` for user ${authInfo.clientId}` : ""
            }`,
          },
        ],
      };
    },
  );
}, {});

// Token verification function
const verifyToken = async (
  req: Request,
  bearerToken?: string,
): Promise<AuthInfo | undefined> => {
  if (!bearerToken) return undefined;

  // Replace with actual token verification logic
  const isValid = bearerToken.startsWith("__TEST_VALUE__");
  if (!isValid) return undefined;

  return {
    token: bearerToken,
    scopes: ["read:stuff"],
    clientId: "user123",
    extra: { userId: "123" },
  };
};

// Wrap handler with authorization
const authHandler = withMcpAuth(handler, verifyToken, {
  required: true,
  requiredScopes: ["read:stuff"],
  resourceMetadataPath: "/.well-known/oauth-protected-resource",
});

export { authHandler as GET, authHandler as POST };
```

## Browser session cookies for WebMCP

The WebMCP bridge uses `fetch` with `credentials: "same-origin"` by default, so it automatically sends the session cookie already held by the browser. `verifyToken` receives the full request and can use that cookie when no bearer token is present:

```typescript
const verifyAuth = async (
  req: Request,
  bearerToken?: string,
): Promise<AuthInfo | undefined> => {
  // Preserve OAuth support for regular MCP clients.
  if (bearerToken) return verifyOAuthToken(bearerToken);

  // Only trust browser cookies on same-origin requests.
  if (req.headers.get("sec-fetch-site") !== "same-origin") return undefined;

  const sessionToken = req.headers
    .get("cookie")
    ?.split(";")
    .map((cookie) => cookie.trim())
    .find((cookie) => cookie.startsWith("session="))
    ?.slice("session=".length);
  if (!sessionToken) return undefined;

  const session = await verifySession(sessionToken);
  if (!session) return undefined;

  return {
    token: [REDACTED],
    scopes: ["read:stuff"],
    clientId: session.userId,
    extra: { userId: session.userId, authMethod: "cookie" },
  };
};

const authHandler = withMcpAuth(handler, verifyAuth, {
  required: true,
  requiredScopes: ["read:stuff"],
});
```

`verifyOAuthToken` and `verifySession` are calls into your auth provider or session store. Keep the session cookie `HttpOnly`, `Secure`, and `SameSite=Lax` or stricter. Do not return or log `authInfo.token` from a tool.

See the [complete cookie-auth route](../examples/auth-cookie/route.ts) and the [WebMCP bridge guide](WEBMCP.md).

## OAuth Protected Resource Metadata

Create `app/.well-known/oauth-protected-resource/route.ts`:

```typescript
import {
  protectedResourceHandler,
  metadataCorsOptionsRequestHandler,
} from "mcp-handler";

const handler = protectedResourceHandler({
  authServerUrls: ["https://auth-server.com"],
});

const corsHandler = metadataCorsOptionsRequestHandler();

export { handler as GET, corsHandler as OPTIONS };
```

This endpoint provides:

- `resource`: The URL of your MCP server
- `authorization_servers`: Array of OAuth authorization server Issuer URLs

The path should match `resourceMetadataPath` in your `withMcpAuth` config (default: `/.well-known/oauth-protected-resource`).

## Authorization Flow

1. Client makes a request with a Bearer token in the Authorization header
2. `verifyToken` validates the token and returns auth info
3. If auth is required and fails → 401 response
4. If required scopes are missing → 403 response
5. On success, auth info is available via `ctx.http?.authInfo` in tool handlers

## CIMD (Client ID Metadata Documents)

The 2026-07-28 MCP spec deprecates Dynamic Client Registration (DCR) in favor of CIMD: OAuth clients identify themselves with an HTTPS URL (`client_id`) that serves their metadata document, removing the need for a registration round-trip.

CIMD is implemented by the **authorization server**, which advertises it via `client_id_metadata_document_supported: true` in its RFC 8414 metadata. As a resource server, your MCP deployment doesn't change beyond what this package already provides — clients discover your authorization servers through the Protected Resource Metadata endpoint above, then negotiate CIMD (or fall back to DCR during the deprecation window) directly with the authorization server. If you operate your own authorization server, enable CIMD there; DCR remains functional for backward compatibility but will be removed in a future spec revision.

