import type { OAuthProtectedResourceMetadata } from "@modelcontextprotocol/server";
import { getPublicUrl } from "../lib/url";

/**
 * CORS headers for OAuth Protected Resource Metadata endpoint.
 * Configured to allow any origin to make the endpoint accessible to web-based MCP clients.
 */
const corsHeaders = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, OPTIONS",
    "Access-Control-Allow-Headers": "*",
    "Access-Control-Max-Age": "86400",
};

/**
 * OAuth 2.0 Protected Resource Metadata endpoint based on RFC 9728.
 * @see https://datatracker.ietf.org/doc/html/rfc9728
 *
 * @param authServerUrls - Array of issuer URLs of the OAuth 2.0 Authorization Servers.
 *                        These should match the "issuer" field in the authorization servers'
 *                        OAuth metadata (RFC 8414).
 * @param resourceUrl - Optional explicit resource URL override. When provided, this URL is
 *                      used instead of deriving it from the request. Use this when running
 *                      behind a proxy that doesn't set standard forwarding headers.
 *                      If not provided, the URL is automatically detected from proxy headers
 *                      (X-Forwarded-Host, X-Forwarded-Proto, Forwarded) or falls back to req.url.
 */
export function protectedResourceHandler({
    authServerUrls,
    resourceUrl: explicitResourceUrl,
}: {
    authServerUrls: string[];
    resourceUrl?: string;
}) {
    return (req: Request) => {
        let resource: string;

        if (explicitResourceUrl) {
            // Use explicit override if provided
            resource = explicitResourceUrl;
        } else {
            // Auto-detect from proxy headers or req.url
            const publicUrl = getPublicUrl(req);

            publicUrl.pathname = publicUrl.pathname
              .replace(/^\/\.well-known\/[^\/]+/, "");

            // The URL class does not allow for empty `pathname` and will replace it
            // with "/". Here, we correct that.
            resource = publicUrl.pathname === '/'
              ? publicUrl.toString().replace(/\/$/, '')
              : publicUrl.toString();
        }

        const metadata = generateProtectedResourceMetadata({
            authServerUrls,
            resourceUrl: resource,
        });

        return new Response(JSON.stringify(metadata), {
            headers: {
                ...corsHeaders,
                "Cache-Control": "max-age=3600",
                "Content-Type": "application/json",
            },
        });
    };
}

/**
 * Generates protected resource metadata for the given auth server URLs and
 * protected resource identifier. The protected resource identifier, as defined
 * in RFC 9728, should be a a URL that uses the https scheme and has no fragment
 * component.
 *
 * @param authServerUrls - Array of issuer URLs of the authorization servers. Each URL should 
 *                        match the "issuer" field in the respective authorization server's 
 *                        OAuth metadata (RFC 8414).
 * @param resourceUrl - the protected resource identifier
 * @param additionalMetadata - Additional metadata fields to include in the response
 * @returns Protected resource metadata, serializable to JSON
 */
export function generateProtectedResourceMetadata({
    authServerUrls,
    resourceUrl,
    additionalMetadata,
}: {
    authServerUrls: string[];
    resourceUrl: string;
    additionalMetadata?: Partial<OAuthProtectedResourceMetadata>;
}): OAuthProtectedResourceMetadata {
    return Object.assign(
        {
            resource: resourceUrl,
            authorization_servers: authServerUrls
        },
        additionalMetadata
    );
}

/**
 * CORS options request handler for OAuth metadata endpoints.
 * Necessary for MCP clients that operate in web browsers.
 */
export function metadataCorsOptionsRequestHandler() {
    return () => {
        return new Response(null, {
            status: 200,
            headers: corsHeaders,
        });
    };
}

import type { AuthInfo } from "@modelcontextprotocol/server";
import {
  OAuthError,
  OAuthErrorCode,
  bearerAuthChallengeResponse,
} from "@modelcontextprotocol/server";
import { getPublicOrigin } from "../lib/url";

declare global {
  interface Request {
    auth?: AuthInfo;
  }
}

export function withMcpAuth(
  handler: (req: Request) => Response | Promise<Response>,
  verifyToken: (
    req: Request,
    bearerToken?: string,
  ) => AuthInfo | undefined | Promise<AuthInfo | undefined>,
  {
    required = false,
    resourceMetadataPath = "/.well-known/oauth-protected-resource",
    requiredScopes,
    resourceUrl,
  }: {
    required?: boolean;
    resourceMetadataPath?: string;
    requiredScopes?: string[];
    /**
     * Explicit resource URL override. When provided, this URL is used as the
     * origin for constructing the resource_metadata URL. Use this when running
     * behind a proxy that doesn't set standard forwarding headers, or when you
     * need to specify a specific public URL.
     *
     * If not provided, the origin is automatically detected from proxy headers
     * (X-Forwarded-Host, X-Forwarded-Proto, Forwarded) or falls back to req.url.
     */
    resourceUrl?: string;
  } = {},
) {
  return async (req: Request) => {
    const origin = resourceUrl ?? getPublicOrigin(req);
    const resourceMetadataUrl = `${origin}${resourceMetadataPath}`;
    const challengeOptions = { requiredScopes, resourceMetadataUrl };

    const authHeader = req.headers.get("Authorization");
    const [type, token] = authHeader?.split(" ") || [];

    // Only support bearer token as per the MCP spec
    // https://modelcontextprotocol.io/specification/2025-03-26/basic/authorization#2-6-1-token-requirements
    const bearerToken = [REDACTED] === "bearer" ? token : undefined;

    let authInfo: AuthInfo | undefined;
    try {
      authInfo = await verifyToken(req, bearerToken);
    } catch (error) {
      console.error("Unexpected error authenticating bearer token:", error);
      return bearerAuthChallengeResponse(
        new OAuthError(OAuthErrorCode.InvalidToken, "Invalid token"),
        challengeOptions,
      );
    }

    try {
      if (required && !authInfo) {
        throw new OAuthError(
          OAuthErrorCode.InvalidToken,
          "No authorization provided",
        );
      }

      if (!authInfo) {
        return handler(req);
      }

      // Check if token has the required scopes (if any)
      if (requiredScopes?.length) {
        const hasAllScopes = requiredScopes.every((scope) =>
          authInfo!.scopes.includes(scope),
        );

        if (!hasAllScopes) {
          throw new OAuthError(
            OAuthErrorCode.InsufficientScope,
            "Insufficient scope",
          );
        }
      }

      // Check if the token is expired
      if (authInfo.expiresAt && authInfo.expiresAt < Date.now() / 1000) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, "Token has expired");
      }

      // Set auth info on the request object after successful verification
      req.auth = authInfo;

      return handler(req);
    } catch (error) {
      if (!OAuthError.isInstance(error)) {
        console.error("Unexpected error authenticating bearer token:", error);
      }
      // Maps invalid_token → 401, insufficient_scope → 403 (both with a
      // WWW-Authenticate challenge advertising resource_metadata), anything
      // unexpected → 500 server_error.
      return bearerAuthChallengeResponse(error, challengeOptions);
    }
  };
}

import {
  createMcpHandler as createSdkMcpHandler,
  McpServer,
  type CreateMcpHandlerOptions as SdkMcpHandlerOptions,
  type ServerOptions as McpServerOptions,
} from "@modelcontextprotocol/server";
import type {
  McpEvent,
  McpRequestEvent,
  McpErrorEvent,
} from "../lib/log-helper";
import { createEvent } from "../lib/log-helper";
import {
  createWebMcpScriptHandler,
  type WebMcpScriptHandlerOptions,
} from "../webmcp/script-handler";

export type WebMcpOptions = Omit<WebMcpScriptHandlerOptions, "endpoint">;

/**
 * Options for the MCP handler: the SDK's `ServerOptions` (capabilities,
 * instructions, ...) plus handler-level extras.
 */
export type McpHandlerOptions = McpServerOptions & {
  /**
   * Maximum number of concurrent `subscriptions/listen` streams.
   * Set to `0` to reject subscriptions without opening an SSE stream.
   * @default 1024
   */
  maxSubscriptions?: SdkMcpHandlerOptions["maxSubscriptions"];
  /**
   * Name and version reported to clients during initialization.
   */
  serverInfo?: {
    name: string;
    version: string;
  };
  /**
   * If true, enables console logging.
   * @default false
   */
  verboseLogs?: boolean;
  /**
   * Callback function that receives MCP events.
   * This can be used to track analytics, debug issues, or implement custom behaviors.
   */
  onEvent?: (event: McpEvent) => void;
  /**
   * Publishes an allowlisted subset of this server's tools to in-page agents
   * through WebMCP. Load the generated bridge from the MCP route with the
   * `?webmcp-script` query parameter.
   *
   * @experimental WebMCP is an early-stage browser API.
   */
  experimental_webMcp?: WebMcpOptions;
};

export function initializeMcpApiHandler(
  initializeServer:
    | ((server: McpServer) => Promise<void>)
    | ((server: McpServer) => void),
  options: McpHandlerOptions = {},
): (req: Request) => Promise<Response> {
  const {
    serverInfo = {
      name: "mcp-typescript server on vercel",
      version: "0.1.0",
    },
    verboseLogs = false,
    onEvent,
    maxSubscriptions,
    experimental_webMcp,
    ...mcpServerOptions
  } = options;

  // Validate WebMCP configuration when the handler is created rather than on
  // the first request. The real endpoint is inferred from the script request.
  if (experimental_webMcp) {
    createWebMcpScriptHandler({
      ...experimental_webMcp,
      endpoint: "/",
    });
  }

  const emitError = (error: Error) => {
    if (verboseLogs) {
      console.error("MCP handler error:", error);
    }
    onEvent?.(
      createEvent<McpErrorEvent>({
        type: "ERROR",
        error,
        source: "request",
        severity: "error",
      }),
    );
  };

  // The SDK handler serves the 2026-07-28 protocol (stateless, per-request
  // envelope, server/discover) and falls back to stateless serving for
  // 2025-era Streamable HTTP clients. A fresh McpServer is constructed per
  // request via the factory.
  const sdkHandler = createSdkMcpHandler(
    async () => {
      const server = new McpServer(serverInfo, mcpServerOptions);
      await initializeServer(server);
      return server;
    },
    {
      legacy: "stateless",
      onerror: emitError,
      maxSubscriptions,
    },
  );

  return async function mcpApiHandler(req: Request): Promise<Response> {
    if (
      experimental_webMcp &&
      (req.method === "GET" || req.method === "HEAD")
    ) {
      const scriptUrl = new URL(req.url);
      if (scriptUrl.searchParams.has("webmcp-script")) {
        scriptUrl.searchParams.delete("webmcp-script");
        return createWebMcpScriptHandler({
          ...experimental_webMcp,
          endpoint: scriptUrl.toString(),
        })(req);
      }
    }

    let method: string | undefined;
    let parsedBody: unknown;
    const started = Date.now();

    if (
      req.method === "POST" &&
      (req.headers.get("content-type") || "").includes("application/json")
    ) {
      try {
        parsedBody = await req.clone().json();
        if (
          typeof parsedBody === "object" &&
          parsedBody !== null &&
          "method" in parsedBody
        ) {
          method = String((parsedBody as { method: unknown }).method);
          onEvent?.(
            createEvent<McpRequestEvent>({
              type: "REQUEST_RECEIVED",
              method,
              parameters: redactEventSecret(parsedBody),
              status: "success",
            }),
          );
        }
      } catch {
        // Malformed JSON is rejected by the SDK handler below.
      }
    }

    try {
      // withMcpAuth attaches the verified AuthInfo to this Request. Pass it
      // explicitly so the SDK exposes it as ctx.http?.authInfo.
      const response = await sdkHandler.fetch(req, {
        authInfo: req.auth,
        parsedBody,
      });

      if (method) {
        onEvent?.(
          createEvent<McpRequestEvent>({
            type: "REQUEST_COMPLETED",
            method,
            duration: Date.now() - started,
            status: response.ok ? "success" : "error",
          }),
        );
      }
      return response;
    } catch (error) {
      emitError(error instanceof Error ? error : new Error(String(error)));
      throw error;
    }
  };
}

function redactEventSecret(body: object): object {
  const request = body as { method?: unknown; params?: unknown };
  if (
    typeof request.method !== "string" ||
    !request.method.startsWith("events/") ||
    !request.params ||
    typeof request.params !== "object"
  )
    return body;
  const params = request.params as { delivery?: unknown };
  if (
    !params.delivery ||
    typeof params.delivery !== "object" ||
    !("secret" in params.delivery)
  )
    return body;
  return {
    ...body,
    params: {
      ...params,
      delivery: { ...params.delivery, secret: "[REDACTED]" },
    },
  };
}

/**
 * Options for the WebMCP bridge script endpoint.
 */
export type WebMcpScriptHandlerOptions = {
  /**
   * URL of the MCP endpoint the script talks to. May be a path relative to
   * the page origin ("/api/mcp") or an absolute URL.
   */
  endpoint: string;
  /**
   * Explicit allowlist of tool names exposed to in-page agents. Tools not
   * listed here are never registered with the browser, even though they
   * remain reachable through the MCP endpoint itself.
   */
  tools: string[];
  /**
   * Credentials mode for the tool-call fetches issued from the page.
   * @default "same-origin"
   */
  credentials?: "same-origin" | "include" | "omit";
  /**
   * Value served in the script response's Cache-Control header.
   * @default "public, max-age=300"
   */
  cacheControl?: string;
};

type ScriptConfig = {
  endpoint: string;
  tools: string[];
  credentials: string;
};

/**
 * Returns a Web-standard handler that serves a small browser script. When
 * loaded in a page, the script lists the tools of the MCP endpoint, filters
 * them down to the configured allowlist, and registers each one with the
 * page's WebMCP provider (`navigator.modelContext` / `document.modelContext`)
 * so in-page agents can call them. Tool calls run through `fetch` and carry
 * the user's session according to the configured credentials mode.
 *
 * WebMCP is an early-stage W3C proposal; in browsers without a provider (or
 * polyfill) the script is a no-op.
 */
export function createWebMcpScriptHandler(
  options: WebMcpScriptHandlerOptions,
): (req: Request) => Response {
  const {
    endpoint,
    tools,
    credentials = "same-origin",
    cacheControl = "public, max-age=300",
  } = options;

  if (typeof endpoint !== "string" || endpoint.length === 0) {
    throw new Error("createWebMcpScriptHandler: `endpoint` is required");
  }
  if (
    !Array.isArray(tools) ||
    tools.some((name) => typeof name !== "string" || name.length === 0)
  ) {
    throw new Error(
      "createWebMcpScriptHandler: `tools` must be an array of tool names — only allowlisted tools are exposed to the web",
    );
  }

  const script = buildScript({ endpoint, tools, credentials });
  const headers = {
    "content-type": "text/javascript; charset=utf-8",
    "cache-control": cacheControl,
  };

  return function webMcpScriptHandler(req: Request): Response {
    if (req.method === "HEAD") {
      return new Response(null, { status: 200, headers });
    }
    if (req.method !== "GET") {
      return new Response("Method not allowed", {
        status: 405,
        headers: { allow: "GET, HEAD" },
      });
    }
    return new Response(script, { status: 200, headers });
  };
}

function buildScript(config: ScriptConfig): string {
  // "<" is escaped so the config can never terminate an inline <script> tag.
  const configJson = JSON.stringify(config).replace(/</g, "\\u003c");

  return `(() => {
  "use strict";
  const config = ${configJson};
  const provider = [
    typeof document !== "undefined" && document.modelContext,
    typeof navigator !== "undefined" && navigator.modelContext,
  ].find((candidate) => candidate && typeof candidate.registerTool === "function");
  if (!provider || typeof provider.registerTool !== "function") {
    return;
  }

  let protocolVersion = null;
  let requestId = 0;

  async function rpc(method, params, isNotification, signal) {
    const body = { jsonrpc: "2.0", method };
    if (params !== undefined) body.params = params;
    if (!isNotification) body.id = ++requestId;
    const headers = {
      "content-type": "application/json",
      accept: "application/json, text/event-stream",
    };
    if (protocolVersion) headers["mcp-protocol-version"] = protocolVersion;
    const res = await fetch(config.endpoint, {
      method: "POST",
      credentials: config.credentials,
      headers,
      body: JSON.stringify(body),
      signal,
    });
    if (isNotification) return null;
    if (!res.ok) {
      throw new Error("MCP request failed: HTTP " + res.status);
    }
    const contentType = res.headers.get("content-type") || "";
    if (contentType.includes("text/event-stream")) {
      return parseSse(await res.text(), body.id);
    }
    return unwrap(await res.json(), body.id);
  }

  function parseSse(text, id) {
    for (const event of text.split(/\\r?\\n\\r?\\n/)) {
      const data = event
        .split(/\\r?\\n/)
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).replace(/^ /, ""))
        .join("\\n");
      if (!data) continue;
      let message;
      try {
        message = JSON.parse(data);
      } catch {
        continue;
      }
      if (
        message &&
        message.id === id &&
        ("result" in message || "error" in message)
      ) {
        return unwrap(message, id);
      }
    }
    throw new Error("No MCP response found in event stream");
  }

  function unwrap(message, id) {
    if (message && message.error) {
      throw new Error(
        message.error.message || "MCP error " + message.error.code,
      );
    }
    if (!message || message.id !== id) {
      throw new Error("Unexpected MCP response");
    }
    return message.result;
  }

  (async () => {
    const init = await rpc("initialize", {
      protocolVersion: "2025-06-18",
      capabilities: {},
      clientInfo: { name: "mcp-handler/webmcp", version: "1.0.0" },
    });
    protocolVersion = (init && init.protocolVersion) || "2025-06-18";
    await rpc("notifications/initialized", undefined, true).catch(() => null);

    let cursor;
    do {
      const listed = await rpc("tools/list", cursor ? { cursor } : {});
      for (const tool of (listed && listed.tools) || []) {
        if (!config.tools.includes(tool.name)) continue;
        try {
          await provider.registerTool({
            name: tool.name,
            title: tool.title || tool.annotations?.title || tool.name,
            description: tool.description || tool.title || tool.annotations?.title || tool.name,
            inputSchema: tool.inputSchema,
            annotations: { readOnlyHint: tool.annotations?.readOnlyHint === true },
            execute: (args, options) =>
              rpc("tools/call", { name: tool.name, arguments: args || {} }, false, options?.signal),
          });
        } catch (error) {
          console.warn("[mcp-handler/webmcp] failed to register tool " + tool.name + ":", error);
        }
      }
      cursor = listed && listed.nextCursor;
    } while (cursor);
  })().catch((error) => {
    console.warn("[mcp-handler/webmcp] failed to register tools:", error);
  });
})();
`;
}

